from pathlib import Path
p=Path('/mnt/data/work/s80/index.html')
s=p.read_text(encoding='utf-8')
css='''<style id="s80-online-clan-css">.s80Hero{padding:14px;border-radius:16px;background:linear-gradient(135deg,#25201a,#171717);border:1px solid #59462b;margin-bottom:10px}.s80Hero b{display:block;font-size:19px}.s80Hero small,.s80Grid small,.s80Member small,.s80Clan small{display:block;opacity:.7;margin-top:4px}.s80Tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin:8px 0}.s80Tabs button{padding:8px 3px;border:1px solid #333;background:#171717;color:#ddd;border-radius:10px;font-size:11px}.s80Tabs button.active{border-color:#b98a42;background:#2a2115}.s80Grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:8px 0}.s80Grid>div{padding:10px 5px;text-align:center;border:1px solid #333;border-radius:12px;background:#181818}.s80Grid b{display:block;font-size:18px;margin-top:4px}.s80Card{padding:12px;margin:8px 0;border:1px solid #333;border-radius:14px;background:#171717}.s80Card p{opacity:.78;font-size:13px;line-height:1.4}.s80Btn{margin-top:8px;width:100%;padding:10px;border:1px solid #76572e;border-radius:10px;background:#241b10;color:#f1d39b}.s80Btn.danger{border-color:#713b3b;background:#241313}.s80Member,.s80Clan{display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid #292929}.s80Member:last-child,.s80Clan:last-child{border-bottom:0}.s80Input{box-sizing:border-box;width:100%;padding:11px;margin-top:8px;border-radius:9px;border:1px solid #444;background:#101010;color:#fff}.s80Clan .s80Btn{width:auto;margin:0;padding:7px 10px}</style>'''
needle='</head>'
s=s.replace(needle,css+'\n</head>',1)
s=s.replace('</body>','<script id="s80-online-clan-js">'+Path('/mnt/data/work/s80/s80-client.js').read_text(encoding='utf-8')+'</script>\n</body>',1)
p.write_text(s,encoding='utf-8')
